import mapboxgl, { CustomLayerInterface } from "mapbox-gl";

class CanvasPolygonLayer implements mapboxgl.CustomLayerInterface {
    id: string;
    type: 'custom';
    renderingMode: '2d';
    map: mapboxgl.Map;
    canvas: HTMLCanvasElement;
    context: CanvasRenderingContext2D;
    polygonsData: any;
    popup?: mapboxgl.Popup;
    hoveredPolygonId: number | null = null;

    constructor(map: mapboxgl.Map, polygonsData: any) {
        this.map = map;
        this.id = 'polygon-layer';
        this.type = 'custom';
        this.renderingMode = '2d';
        this.polygonsData = polygonsData;

        this.canvas = document.createElement('canvas');
        this.canvas.style.position = 'absolute';
        this.canvas.style.top = '0';
        this.canvas.style.left = '0';
        const context = this.canvas.getContext('2d');
        if (!context) throw new Error('Failed to get 2D context');
        this.context = context;

        this.canvas.addEventListener('mousemove', this.onMouseMove.bind(this));
        this.canvas.addEventListener('click', this.onClick.bind(this));

        this.cachedScreenPolygon = [];
    }

    private onMouseMove(e: MouseEvent): void {
        const rect = this.canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        this.hoveredPolygonId = null;
        this.canvas.style.cursor = '';

        this.polygonsData.features.forEach((feature: any, index: number) => {
            if (this.isPointInPolygon([x, y], feature.geometry.coordinates)) {
                this.hoveredPolygonId = index;
                this.canvas.style.cursor = 'pointer';
            }
        });

        this.map.triggerRepaint();
    }

    private onClick(e: MouseEvent): void {
        const rect = this.canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;



        this.polygonsData.features.forEach((feature: any, index: number) => {
            if (this.isPointInPolygon([x, y], feature.geometry.coordinates)) {
                if (this.popup) {
                    this.popup.remove();
                }

                this.popup = new mapboxgl.Popup()
                    .setLngLat(feature.geometry.coordinates[0][0])
                    .setHTML(`
                        <div style="padding: 10px;">
                            <h3>Polygon Information</h3>
                            <p>${feature.properties.description || 'No description'}</p>
                        </div>
                    `)
                    .addTo(this.map);
            }
        });
    }

    // private isPointInPolygon(point: [number, number], polygon: number[][][]): boolean {
    //     const [mouseX, mouseY] = point;
    //     // let isInside = false;

        
    //     const screenPolygon = polygon[0].map(coord => this.map.project(coord));
    //     console.log(mouseX, mouseY, screenPolygon)
        
    //     let isInside = false;
    
    //     // Ray-Casting 알고리즘을 사용하여 점이 폴리곤 내부에 있는지 확인
    //     for (let i = 0, j = screenPolygon.length - 1; i < screenPolygon.length; j = i++) {
    //         const { x: xi, y: yi } = screenPolygon[i];
    //         const { x: xj, y: yj } = screenPolygon[j];
    
    //         const intersect = yi > mouseY !== yj > mouseY && 
    //             mouseX < ((xj - xi) * (mouseY - yi)) / (yj - yi) + xi;
    
    //         if (intersect) isInside = !isInside;
    //     }
    
    //     return isInside;
    // }
    private cachedScreenPolygon: { polygonId: string; coordinates: { x: number; y: number }[] }[] = [];
    private isPointInPolygon(point: [number, number], polygon: number[][][], polygonId: string): boolean {

      // console.log(polygon)

      if (polygon.length > 1) {
        return this.isPointInPolygonMul(point, polygon)
      }

        const[mouseX, mouseY] = point;
        const screenPolygon = polygon[0].map(coord => this.map.project(coord));

        let isInside = false;
        for (let i = 0, j = screenPolygon.length - 1; i < screenPolygon.length; j = i++) {
            const { x: xi, y: yi } = screenPolygon[i];
            const { x: xj, y: yj } = screenPolygon[j];
        
            const intersect = yi > mouseY !== yj > mouseY && mouseX < ((xj - xi) * (mouseY - yi)) / (yj - yi) + xi;

            // console.log(`Edge (${i}-${j}): Intersect = ${intersect}`);
        
            if (intersect) isInside = !isInside;
        }

        return isInside;
    }

    private isPointInPolygonMul(point: [number, number], polygon: number[][][], polygonId: string): boolean {
      // console.log(polygon);
      
      const [mouseX, mouseY] = point;
      let isInside = false;
  
      for (const singlePolygon of polygon) {
          const screenPolygon = singlePolygon.map(coord => {
              // Ensure coord is in the correct format
              if (Array.isArray(coord) && coord.length === 2) {
                  return this.map.project(coord as [number, number]);
              } else if (coord.lng !== undefined && coord.lat !== undefined) {
                  return this.map.project({ lng: coord.lng, lat: coord.lat });
              } else if (coord.lon !== undefined && coord.lat !== undefined) {
                  return this.map.project({ lon: coord.lon, lat: coord.lat });
              } else {
                  console.warn('Invalid coordinate format:', coord);
                  return null; // Handle invalid coordinate format
              }
          }).filter(coord => coord !== null); // Filter out invalid coordinates
  
          let currentPolygonInside = false;
          for (let i = 0, j = screenPolygon.length - 1; i < screenPolygon.length; j = i++) {
              const { x: xi, y: yi } = screenPolygon[i];
              const { x: xj, y: yj } = screenPolygon[j];
          
              const intersect = yi > mouseY !== yj > mouseY && mouseX < ((xj - xi) * (mouseY - yi)) / (yj - yi) + xi;
  
              if (intersect) currentPolygonInside = !currentPolygonInside;
          }
  
          if (currentPolygonInside) isInside = true;
      }
  
      return isInside;
  }
  
  

    onAdd(map: mapboxgl.Map): void {
        this.resizeCanvas();
        map.getCanvasContainer().appendChild(this.canvas);
        map.on('resize', this.resizeCanvas.bind(this));
    }

    // render(): boolean {
    //     const context = this.context;

    //     context.clearRect(0, 0, this.canvas.width, this.canvas.height);

    //     this.polygonsData.features.forEach((feature: any, index: number) => {
    //         const coordinates = feature.geometry.coordinates[0].map((coord: any) => this.map.project(coord));

    //         console.log(coordinates)

    //         context.beginPath();
    //         coordinates.forEach((coord: mapboxgl.Point, i: number) => {
    //             if (i === 0) {
    //                 context.moveTo(coord.x, coord.y);
    //             } else {
    //                 context.lineTo(coord.x, coord.y);
    //             }
    //         });
    //         context.closePath();

    //         if (this.hoveredPolygonId === index) {
    //             context.fillStyle = 'rgba(255, 0, 0, 0.5)';
    //         } else {
    //             context.fillStyle = 'rgba(0, 0, 255, 0.5)';
    //         }

    //         context.fill();
    //         context.strokeStyle = '#FFFFFF';
    //         context.lineWidth = 2;
    //         context.stroke();
    //     });

    //     return true;
    // }
      render(): boolean {
        const context = this.context;
    
        context.clearRect(0, 0, this.canvas.width, this.canvas.height);
    
        this.polygonsData.features.forEach((feature: any, index: number) => {
            // Check if it's a MultiPolygon
            if (feature.geometry.type === 'MultiPolygon') {
                feature.geometry.coordinates.forEach((polygon: any) => {
                    const coordinates = polygon[0].map((coord: any) => this.map.project(coord));
    
                    context.beginPath();
                    coordinates.forEach((coord: mapboxgl.Point, i: number) => {
                        if (i === 0) {
                            context.moveTo(coord.x, coord.y);
                        } else {
                            context.lineTo(coord.x, coord.y);
                        }
                    });
                    context.closePath();
    
                    if (this.hoveredPolygonId === index) {
                        context.fillStyle = 'rgba(255, 0, 0, 0.5)';
                    } else {
                        context.fillStyle = 'rgba(0, 0, 255, 0.5)';
                    }
    
                    context.fill();
                    context.strokeStyle = '#FFFFFF';
                    context.lineWidth = 2;
                    context.stroke();
                });
            } else if (feature.geometry.type === 'Polygon') {
                // Handle normal polygons
                const coordinates = feature.geometry.coordinates[0].map((coord: any) => this.map.project(coord));
    
                context.beginPath();
                coordinates.forEach((coord: mapboxgl.Point, i: number) => {
                    if (i === 0) {
                        context.moveTo(coord.x, coord.y);
                    } else {
                        context.lineTo(coord.x, coord.y);
                    }
                });
                context.closePath();
    
                if (this.hoveredPolygonId === index) {
                    context.fillStyle = 'rgba(255, 0, 0, 0.5)';
                } else {
                    context.fillStyle = 'rgba(0, 0, 255, 0.5)';
                }
    
                context.fill();
                context.strokeStyle = '#FFFFFF';
                context.lineWidth = 2;
                context.stroke();
            }
        });
    
        return true;
    }
  

    onRemove(): void {
        if (this.popup) {
            this.popup.remove();
        }
        if (this.canvas.parentNode) {
            this.canvas.parentNode.removeChild(this.canvas);
        }
        this.map.off('resize', this.resizeCanvas);
    }

    private resizeCanvas(): void {
        const mapCanvas = this.map.getCanvas();
        this.canvas.width = mapCanvas.width;
        this.canvas.height = mapCanvas.height;
    }
}


class CanvasPointLayer implements CustomLayerInterface {
    id: string;
    type: 'custom';
    renderingMode: '2d';
    map: mapboxgl.Map;
    canvas: HTMLCanvasElement;
    context: CanvasRenderingContext2D;
    pointsData: any;
    popup?: mapboxgl.Popup;
    hoveredPointId: number | null = null;
    animationStartTime: number;

    constructor(map: mapboxgl.Map, pointsData: any) {
        this.map = map;
        this.id = 'points-layer';
        this.type = 'custom';
        this.renderingMode = '2d';
        this.pointsData = pointsData;
        this.animationStartTime = Date.now();
        
        this.canvas = document.createElement('canvas');
        this.canvas.style.position = 'absolute';
        this.canvas.style.top = '0';
        this.canvas.style.left = '0';
        const context = this.canvas.getContext('2d');
        if (!context) throw new Error('Failed to get 2D context');
        this.context = context;

        this.canvas.addEventListener('mousemove', this.onMouseMove.bind(this));
        this.canvas.addEventListener('click', this.onClick.bind(this));

        this.animate();
    }

    private animate = () => {
        this.map.triggerRepaint();
        requestAnimationFrame(this.animate);
    }

    private getAnimatedSize(baseSize: number, index: number): number {
        const time = Date.now() - this.animationStartTime;

        const phase = index * (Math.PI / 4);
        const scale = 1 + (Math.sin(time * 0.002 + phase) * 0.2);
        return baseSize * scale;
    }

    private getHoverColor(baseColor: string): string {
        const time = Date.now() - this.animationStartTime;
        const hue = (time * 0.1) % 360;
        return `hsl(${hue}, 100%, 50%)`;
    }
    private onMouseMove(e: MouseEvent): void {
        const rect = this.canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        this.canvas.style.cursor = '';
        
        this.hoveredPointId = null;
        for (let i = 0; i < this.pointsData.features.length; i++) {
            const feature = this.pointsData.features[i];
            if (this.isPointUnderMouse(
                feature.geometry.coordinates, 
                x, 
                y, 
                feature.properties.size ? feature.properties.size : 5
            )) {
                this.hoveredPointId = i;
                this.canvas.style.cursor = 'pointer';
                break;
            }
        }

        this.map.triggerRepaint();
    }
    private onClick(e: MouseEvent): void {
        const rect = this.canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;

        for (let i = 0; i < this.pointsData.features.length; i++) {
            const feature = this.pointsData.features[i];
            if (this.isPointUnderMouse(
                feature.geometry.coordinates, 
                x, 
                y, 
                feature.properties.size
            )) {
                // console.log('feature.properties.size')

                if (this.popup) {
                    this.popup.remove();
                }

                this.popup = new mapboxgl.Popup()
                    .setLngLat(feature.geometry.coordinates)
                    .setHTML(`
                        <div style="padding: 10px;">
                            <h3>Point Information</h3>
                            <p>Size: ${feature.properties.size}</p>
                            <p>Color: ${feature.properties.color}</p>
                            ${feature.properties.description ? 
                                `<p>${feature.properties.description}</p>` : 
                                ''}
                        </div>
                    `)
                    .addTo(this.map);
                break;
            }
        }
    }
    private isPointUnderMouse(point: number[], mouseX: number, mouseY: number, radius: number): boolean {
        const pixel = this.map.project(point);
        const distance = Math.sqrt(
            Math.pow(pixel.x - mouseX, 2) + 
            Math.pow(pixel.y - mouseY, 2)
        );
        // console.log(distance, radius)
        return distance <= radius;
    }
      onAdd(map: mapboxgl.Map): void {
        this.resizeCanvas();
        map.getCanvasContainer().appendChild(this.canvas);
        map.on('resize', this.resizeCanvas.bind(this));
    }
    render(): boolean {
        const context = this.context;

        // console.log(this.hoveredPointId);
        
        context.clearRect(0, 0, this.canvas.width, this.canvas.height);


        this.pointsData.features.forEach((feature, index) => {
          const point = feature.geometry.coordinates;
          const properties = feature.properties;
          
          
          const pixel = this.map.project(point);
          const animatedSize = this.getAnimatedSize(properties.size? properties.size : 5, index);
        
            // console.log(pixel)

            context.beginPath();
            context.arc(
                pixel.x,
                pixel.y,
                animatedSize,
                0,
                2 * Math.PI
            );


            if (this.hoveredPointId === index) {
                context.fillStyle = '#f00' // this.getHoverColor(properties.color);
                
                context.shadowColor = 'white';
                context.shadowBlur = 20;
            } else {
                context.fillStyle = '#00f'  // properties.color;
                context.shadowBlur = 0;
            }
            
            context.fill();

            context.strokeStyle = '#FFFFFF';
            context.lineWidth = 2;
            context.stroke();

            context.shadowBlur = 0;
        });

        return true;
    }

    onRemove(): void {
        if (this.popup) {
            this.popup.remove();
        }
        if (this.canvas.parentNode) {
            this.canvas.parentNode.removeChild(this.canvas);
        }
        this.map.off('resize', this.resizeCanvas);
    }
        private resizeCanvas(): void {
        const mapCanvas = this.map.getCanvas();
        this.canvas.width = mapCanvas.width;
        this.canvas.height = mapCanvas.height;
    }
}



